import{_ as t,o as i,c as e,a2 as l}from"./chunks/framework.mqZn2l2k.js";const I=JSON.parse('{"title":"《从 n8n 到 Mini-n8n：从零构建 AI Agent Workflow 平台》大纲","description":"","frontmatter":{},"headers":[],"relativePath":"OUTLINE.md","filePath":"OUTLINE.md","lastUpdated":1791458539000}'),r={name:"OUTLINE.md"};function n(o,a,d,h,c,s){return i(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="《从-n8n-到-mini-n8n-从零构建-ai-agent-workflow-平台》大纲" tabindex="-1">《从 n8n 到 Mini-n8n：从零构建 AI Agent Workflow 平台》大纲 <a class="header-anchor" href="#《从-n8n-到-mini-n8n-从零构建-ai-agent-workflow-平台》大纲" aria-label="Permalink to &quot;《从 n8n 到 Mini-n8n：从零构建 AI Agent Workflow 平台》大纲&quot;">​</a></h1><blockquote><p>参照仓库：<code>n8n-io/n8n</code> @ <code>60ad29f242</code>（<code>packages/cli</code> 版本 2.43.0） 读者目标：读完后，能从零写出一个前后端都能运行、支持 AI Agent 的 Workflow 自动化平台。 写作方式：每章先讲概念，再读 n8n 源码（<code>路径:行号</code>），再在 mini-n8n 里实现，最后给出真实运行结果。</p></blockquote><h2 id="贯穿全书的项目-mini-n8n" tabindex="-1">贯穿全书的项目：mini-n8n <a class="header-anchor" href="#贯穿全书的项目-mini-n8n" aria-label="Permalink to &quot;贯穿全书的项目：mini-n8n&quot;">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th>能力</th><th>章节</th></tr></thead><tbody><tr><td>v0.1</td><td>数据模型、表达式与沙箱、栈式执行引擎、12 个核心节点、CLI</td><td>Part II（4–8 章、Lab 1）</td></tr><tr><td>v0.2</td><td>SQLite 持久化、REST API、生命周期钩子、SSE 推送、凭证加密、Webhook / Schedule 触发器</td><td>Part III（9–12 章、Lab 2）</td></tr><tr><td>v0.3</td><td>Vue 3 + Vue Flow 画布、参数面板（NDV）、表达式预览、运行与调试</td><td>Part IV（13–15 章、Lab 3）</td></tr><tr><td>v0.4</td><td>AI 连接类型、Chat Model（Mock / Ollama / OpenAI 兼容）、Tools Agent、EngineRequest、工具、记忆、Chat Trigger、流式</td><td>Part V（16–21 章、Lab 4）</td></tr><tr><td>v0.5</td><td>RAG（Embeddings、向量存储、检索工具）、Agent as Tool、人工审批（HITL）、结构化输出</td><td>Part VI（22–23 章、Lab 5）</td></tr><tr><td>v1.0</td><td>子工作流、等待与恢复、队列模式 + Worker、Code 节点 Task Runner、多用户与 API Key、Docker 部署</td><td>Part VII（24–28 章、Lab 6）</td></tr></tbody></table><p>默认技术栈：TypeScript monorepo（npm workspaces）、<code>tsx</code>、Vitest、Fastify、<code>node:sqlite</code>、Vue 3 + Pinia + Vue Flow。所有 AI 功能都能用离线的 Mock 模型运行，也用本地 Ollama（<code>qwen2.5:0.5b</code>）验证过。</p><h2 id="part-0-导读" tabindex="-1">Part 0 导读 <a class="header-anchor" href="#part-0-导读" aria-label="Permalink to &quot;Part 0 导读&quot;">​</a></h2><ul><li>第 0 章 本书怎么读：环境、目录、如何读 n8n 源码</li></ul><h2 id="part-i-全景-浅" tabindex="-1">Part I 全景（浅） <a class="header-anchor" href="#part-i-全景-浅" aria-label="Permalink to &quot;Part I 全景（浅）&quot;">​</a></h2><ul><li>第 1 章 从自动化到 AI Agent：Workflow 平台的几种形态</li><li>第 2 章 n8n 架构鸟瞰：monorepo、包依赖、运行时拓扑</li><li>第 3 章 一次执行的完整生命周期 ★：从点击按钮到画布变绿</li></ul><h2 id="part-ii-工作流引擎-→-v0-1" tabindex="-1">Part II 工作流引擎 → v0.1 <a class="header-anchor" href="#part-ii-工作流引擎-→-v0-1" aria-label="Permalink to &quot;Part II 工作流引擎 → v0.1&quot;">​</a></h2><ul><li>第 4 章 数据模型：节点、连接与 items ★</li><li>第 5 章 节点类型系统：description 驱动一切</li><li>第 6 章 表达式引擎：<code>{{ $json }}</code>、数据代理与沙箱</li><li>第 7 章 执行引擎：执行栈与等待区 ★★</li><li>第 8 章 健壮性：错误输出、重试、取消、超时、等待</li><li>Lab 1：mini-n8n v0.1 —— 用 CLI 跑一个带分支、合并和循环的工作流</li></ul><h2 id="part-iii-服务端-→-v0-2" tabindex="-1">Part III 服务端 → v0.2 <a class="header-anchor" href="#part-iii-服务端-→-v0-2" aria-label="Permalink to &quot;Part III 服务端 → v0.2&quot;">​</a></h2><ul><li>第 9 章 持久化：工作流、执行记录与运行数据</li><li>第 10 章 生命周期钩子与实时推送</li><li>第 11 章 凭证：加密存储与注入</li><li>第 12 章 触发器：Webhook、Schedule 与激活</li><li>Lab 2：REST API + Webhook + 定时任务</li></ul><h2 id="part-iv-编辑器-→-v0-3" tabindex="-1">Part IV 编辑器 → v0.3 <a class="header-anchor" href="#part-iv-编辑器-→-v0-3" aria-label="Permalink to &quot;Part IV 编辑器 → v0.3&quot;">​</a></h2><ul><li>第 13 章 画布：Vue Flow 与工作流数据的映射</li><li>第 14 章 节点详情视图（NDV）：参数渲染与表达式编辑</li><li>第 15 章 运行与调试：实时状态、Pin 数据与部分执行</li><li>Lab 3：可视化编排 + 实时执行</li></ul><h2 id="part-v-ai-agent-→-v0-4-★" tabindex="-1">Part V AI Agent → v0.4 ★ <a class="header-anchor" href="#part-v-ai-agent-→-v0-4-★" aria-label="Permalink to &quot;Part V AI Agent → v0.4 ★&quot;">​</a></h2><ul><li>第 16 章 AI 连接类型与 Cluster Node：<code>supplyData</code> 的设计 ★</li><li>第 17 章 Chat Model 抽象：Mock、Ollama 与流式</li><li>第 18 章 Tools Agent：函数调用循环 ★★</li><li>第 19 章 EngineRequest：让引擎来调度工具 ★★</li><li>第 20 章 工具体系：节点即工具、<code>$fromAI</code>、Workflow Tool、MCP</li><li>第 21 章 记忆、Chat Trigger 与流式响应</li><li>Lab 4：从零搭一个能调工具、有记忆的 AI Agent 工作流</li></ul><h2 id="part-vi-高级-ai-→-v0-5" tabindex="-1">Part VI 高级 AI → v0.5 <a class="header-anchor" href="#part-vi-高级-ai-→-v0-5" aria-label="Permalink to &quot;Part VI 高级 AI → v0.5&quot;">​</a></h2><ul><li>第 22 章 RAG：Embeddings、向量存储与检索工具</li><li>第 23 章 多 Agent、人工审批与结构化输出</li><li>Lab 5：知识库问答 + 需人工审批的工具</li></ul><h2 id="part-vii-平台化-深-→-v1-0" tabindex="-1">Part VII 平台化（深）→ v1.0 <a class="header-anchor" href="#part-vii-平台化-深-→-v1-0" aria-label="Permalink to &quot;Part VII 平台化（深）→ v1.0&quot;">​</a></h2><ul><li>第 24 章 子工作流与等待/恢复</li><li>第 25 章 队列模式与横向扩展</li><li>第 26 章 Code 节点的安全：Task Runner</li><li>第 27 章 多用户、权限与开放 API</li><li>第 28 章 部署与可观测</li><li>Lab 6：一键部署的 mini-n8n v1.0</li></ul><h2 id="附录" tabindex="-1">附录 <a class="header-anchor" href="#附录" aria-label="Permalink to &quot;附录&quot;">​</a></h2><ul><li>A 源码阅读地图（概念 → n8n 路径 → mini-n8n 路径）</li><li>B 术语表</li><li>C 横向对比：n8n / Dify / LangGraph</li><li>D 练习参考答案</li></ul>',23)])])}const b=t(r,[["render",n]]);export{I as __pageData,b as default};
